<?php declare(strict_types=1);
$autoActor=$settings->actor();if($autoActor['members_access']==='none')return;
$auto=new \Kulturhus\Verein\CatalogBillingAutomation($db,(string)$_SESSION['actor']);
$failed=input($_POST,'action')==='catalog-automation-change';$source=$failed?$_POST:$_GET;
$id=input($source,'auto_assignment');$first=input($source,'auto_first',\Kulturhus\Verein\CatalogBillingAutomation::today());$mode=input($source,'auto_mode','full');$due=input($source,'auto_due','30');$key=input($source,'auto_key',bin2hex(random_bytes(16)));
$plan=null;$quote=null;$page=null;$history=null;$autoError='';$stale=false;$route=['view'=>'settings','tab'=>$tab,'automation'=>1];
try{
 if($id!==''){
  $plan=$auto->get($id);$history=$auto->history($id,(int)input($_GET,'auto_page','1'));
  $q=$db->prepare('SELECT sc.kind FROM catalog_assignments ca JOIN settings_catalog sc ON sc.club_id=ca.club_id AND sc.id=ca.catalog_id WHERE ca.club_id=? AND ca.id=?');$q->execute([$autoActor['club_id'],$id]);if(($q->fetchColumn()==='service')!==($tab==='services'))throw new DomainException('Tarif im passenden Katalog auswählen.');
  if(!$failed&&!isset($_GET['auto_review'])&&$plan){$first=max($plan['next_on'],\Kulturhus\Verein\CatalogBillingAutomation::today());$mode=$plan['mode'];$due=(string)$plan['due_days'];}
  if(isset($_GET['auto_review'])||$failed||!$plan){$quote=$auto->review($id,$first,$mode);if($failed)$stale=!hash_equals(input($_POST,'auto_fingerprint'),$quote['fingerprint'])||(int)input($_POST,'auto_version')!==(int)($plan['version']??0);}
 }else $page=(new \Kulturhus\Verein\CatalogAssignments($db,(string)$_SESSION['actor']))->page($tab,$_GET);
}catch(DomainException $e){$autoError=$e->getMessage();}
$version=$failed?(int)input($_POST,'auto_version'):(int)($plan['version']??0);
?>
<link rel="stylesheet" href="catalog-pricing.css">
<section class="card catalog-pricing catalog-automation" id="catalog-automation"><h2 tabindex="-1" autofocus>Abrechnungsautomatik</h2><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'settings','tab'=>$tab])) ?>">Zum Katalog</a>
<?php if($autoError): ?><p role="alert"><?= e($autoError) ?></p><?php endif ?>
<?php if($page): ?>
<form method="get" class="settings-search"><?= hidden('view','settings').hidden('tab',$tab).hidden('automation',1) ?><label>Kontakt oder Tarif<input class="form-control" name="pricing_q" value="<?= e($page['q']) ?>" maxlength="150"></label><button class="btn btn-outline theme-secondary">Suchen</button></form>
<div class="catalog-assignment-list"><?php foreach($page['rows']as$row):$ownPlan=$auto->get($row['id']);$linked=\Kulturhus\Verein\ContributionRates::linked($db,$autoActor['club_id'],$row['catalog_id']);$once=$row['catalog_interval']==='once'; ?><article class="catalog-assignment"><div><strong><?= e($row['name']) ?></strong><span><?= e($row['catalog_name']) ?></span><small><?= $ownPlan?($ownPlan['status']==='active'?'Aktiv · '.e(dateDe($ownPlan['next_on'])):'Pausiert'):($linked?'Jahresbeitragslauf':($once?'Einmaliger Tarif':'Ausgeschaltet')) ?></small></div><?php if(!$linked&&!$once&&($row['active']||$ownPlan)): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($route+['auto_assignment'=>$row['id']])) ?>">Automatik öffnen</a><?php endif ?></article><?php endforeach ?></div>
<span><?= $page['total'] ?> Zuweisungen · Seite <?= $page['page'] ?> von <?= $page['pages'] ?></span>
<?php if($page['pages']>1): ?><form method="get" class="settings-actions"><?= hidden('view','settings').hidden('tab',$tab).hidden('automation',1).hidden('pricing_q',$page['q']) ?><label>Zuweisungsseite<input class="form-control" name="pricing_page" type="number" inputmode="numeric" min="1" max="<?= $page['pages'] ?>" value="<?= $page['page'] ?>" required></label><button class="btn btn-outline theme-secondary">Seite öffnen</button></form><?php endif ?>
<?php endif ?>
<?php if($id!==''): ?>
<?php if($plan):$approved=json_decode($plan['approved_quote'],true,512,JSON_THROW_ON_ERROR); ?><article class="catalog-assignment" data-auto-state><div><strong><?= e($approved['contact_name'].' · '.$approved['name']) ?></strong><span><?= $plan['status']==='active'?'Aktiv':'Pausiert' ?></span><small><?= e('Nächste Abrechnung '.dateDe($plan['next_on'])) ?></small><?php if($plan['reason']==='review'): ?><span role="status">Preisgrundlage oder Freigabe prüfen</span><?php endif ?></div>
<?php if($finance->canWrite()&&$plan['status']==='active'): ?><form method="post" data-auto-pause><?= csrf().hidden('action','catalog-automation-change').hidden('auto_assignment',$id).hidden('auto_version',$plan['version']).hidden('auto_first',$plan['next_on']).hidden('auto_mode',$plan['mode']).hidden('auto_due',$plan['due_days']).hidden('auto_fingerprint',$approved['fingerprint']).hidden('auto_key',bin2hex(random_bytes(16))).hidden('auto_enabled',0) ?><button class="btn btn-outline theme-secondary">Automatik pausieren</button></form><?php endif ?></article><?php endif ?>
<details<?= $quote||!$plan||$failed?' open':'' ?>><summary><?= $plan?'Freigabe ändern':'Automatik einrichten' ?></summary>
<form method="get" class="form-grid" data-auto-review><?= hidden('view','settings').hidden('tab',$tab).hidden('automation',1).hidden('auto_assignment',$id).hidden('auto_review',1) ?><label>Erste Abrechnung<input class="form-control" type="date" name="auto_first" min="<?= e(\Kulturhus\Verein\CatalogBillingAutomation::today()) ?>" value="<?= e($first) ?>" required></label><label>Betrag<select class="form-control" name="auto_mode"><option value="full"<?= $mode==='full'?' selected':'' ?>>Voller Tarifbetrag</option><option value="days"<?= $mode==='days'?' selected':'' ?>>Anteilig nach zugewiesenen Tagen</option></select></label><label>Zahlungsfrist in Tagen<input class="form-control" name="auto_due" type="number" inputmode="numeric" min="0" max="90" value="<?= e($due) ?>" required></label><button class="btn btn-outline theme-secondary">Freigabe prüfen</button></form>
<?php if($quote): ?><article class="catalog-assignment" data-auto-price><div><strong><?= e($quote['contact_name'].' · '.$quote['name']) ?></strong><span><?= e(euro($quote['amount_cents'])) ?> brutto · <?= e(['month'=>'monatlich','quarter'=>'vierteljährlich','half'=>'halbjährlich','year'=>'jährlich'][$quote['data']['interval']]) ?></span><small><?= e(dateDe($quote['period_start']).' – '.dateDe($quote['period_end'])) ?></small><small><?= e('Abrechnung am '.dateDe($first).' · danach am '.(int)substr($first,8).'., spätestens Monatsende') ?></small></div></article>
<?php if($stale): ?><p role="alert">Freigabe inzwischen geändert. Neu prüfen.</p><?php endif ?>
<?php if($finance->canWrite()&&!$stale): ?><form method="post" data-auto-activate><?= csrf().hidden('action','catalog-automation-change').hidden('auto_assignment',$id).hidden('auto_version',$version).hidden('auto_first',$first).hidden('auto_mode',$mode).hidden('auto_due',$due).hidden('auto_fingerprint',$failed?input($_POST,'auto_fingerprint'):$quote['fingerprint']).hidden('auto_key',$key).hidden('auto_enabled',1) ?><button class="btn btn-solid theme-primary">Automatik aktivieren</button></form><?php endif ?>
<?php endif ?></details>
<?php if($history&&$history['rows']): ?><details><summary>Abrechnungen · <?= $history['total'] ?></summary><div class="catalog-assignment-list" data-auto-history><?php foreach($history['rows']as$row):$original=json_decode($row['quote_json'],true,512,JSON_THROW_ON_ERROR); ?><article class="catalog-assignment"><div><strong><?= e(dateDe($row['scheduled_on']).' · '.euro($original['amount_cents'])) ?></strong><span><?= $row['status']==='billed'?'Beleg angelegt':'Vorhandener Beleg' ?></span><small><?= e(dateDe($original['period_start']).' – '.dateDe($original['period_end'])) ?></small></div><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'finance','tab'=>'receipts','entry'=>$row['entry_id']])) ?>">Beleg öffnen</a></article><?php endforeach ?></div><?php if($history['pages']>1): ?><form method="get" class="settings-actions"><?= hidden('view','settings').hidden('tab',$tab).hidden('automation',1).hidden('auto_assignment',$id) ?><label>Abrechnungsseite<input class="form-control" type="number" name="auto_page" min="1" max="<?= $history['pages'] ?>" value="<?= $history['page'] ?>" required></label><button class="btn btn-outline theme-secondary">Seite öffnen</button></form><?php endif ?></details><?php endif ?>
<a class="btn btn-outline theme-secondary" href="<?= e(url($route)) ?>">Andere Zuweisung</a>
<?php endif ?></section>
